"""sklearn.utils.deprecation — deprecation decorator."""

import warnings, functools


class deprecated:
    """Class- and function-decorator that emits a deprecation warning."""

    def __init__(self, extra=''):
        self.extra = extra

    def __call__(self, obj):
        @functools.wraps(obj)
        def _wrapped(*args, **kwargs):
            warnings.warn(f'{obj.__name__} is deprecated. {self.extra}',
                          DeprecationWarning, stacklevel=2)
            return obj(*args, **kwargs)
        return _wrapped
